    // cout<<max_total_strength<<endl;
    
    int n ;cin>>n;
    int tst = 3*n;
    vector<ll> a(tst);
    for(int i = 0;i<tst;i++){
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());
    
    vector<ll> pref(tst+1,0);
    for(int i = 0;i<tst;i++){
        pref[i+1] = pref[i] + a[i];
    }
    auto eval = [&](int x,int y){
        return 3LL * pref[tst-2*x-y] + pref[x+2*y] + 2LL*pref[x];
    };
    
    ll best = 0;
    for(int x = 0;x<=n;x++){
        int low = 0,high = n-x;
        
        while(high - low >= 3){
            int mid1 = low + (high - low )/3;
            int mid2 = high - (high - low)/3;
            
            if(eval(x,mid1) < eval(x,mid2)){
                low = mid1;
            }else{
                high = mid2;
            }
        }
        
        for(int y = low ;y<=high;y++){
            ll curr = eval(x,y);
            if(curr > best){
                best = curr;
            }
        }
    }
    cout<<best<<endl;
}
